void glyph_draw(GContext *ctx, const Glyph *glyph, GPoint origin, GColor colour) {
  graphics_context_set_stroke_color(ctx, colour);
  for (int y = 0; y < glyph->h; y++) {
    uint16_t row = glyph->rows[y];
    for (int x = 0; x < glyph->w; x++) {
      if (row & (1 << (glyph->w - 1 - x))) {
        graphics_draw_pixel(ctx, GPoint(origin.x + x, origin.y + y));
      }
    }
  }
}
